// @FIGURE_CODE_BEGIN
/* ─────────── canvas ─────────── */
var fdraw = SVG().addTo(document.getElementById('container')).size('100%','100%');
var FW = 660, FH = 1290;
fdraw.viewbox(0, 0, FW, FH).attr('preserveAspectRatio', 'xMidYMid meet');

var BLUE = '#5b74b8', RED = '#b4392b', YEL = '#faeecb', GRAY = '#8a8a8a';

/* ─────────── text helpers ─────────── */
function txt(p, x, y, s, size, o) {
  o = o || {};
  var t = p.text(String(s));
  t.font({ family: 'sans-serif', size: size, anchor: o.anchor || 'middle',
           style: o.italic ? 'italic' : 'normal', weight: o.weight || 'normal' });
  t.fill(o.fill || '#000');
  t.attr({ x: x, y: y });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
  return t;
}
function chem(p, x, y, size, parts, o) {
  o = o || {};
  var t = p.text(function (add) {
    var cur = 0;
    for (var i = 0; i < parts.length; i++) {
      var it = parts[i], k = it.k || 'n';
      var sp = add.tspan(it.t);
      var sh = (k === 'sub') ? 0.30 : (k === 'sup' ? -0.45 : 0);
      sp.font({ size: (k === 'sub' || k === 'sup') ? size * 0.7 : size,
                style: (k === 'it') ? 'italic' : 'normal' });
      sp.attr('dy', (sh - cur) * size);
      cur = sh;
    }
  });
  t.font({ family: 'sans-serif', size: size, anchor: o.anchor || 'start' });
  t.fill(o.fill || '#000');
  t.attr({ x: x, y: y });
  if (o.halo) t.attr({ 'paint-order': 'stroke', stroke: '#fff', 'stroke-width': 3.2, 'stroke-linejoin': 'round' });
  return t;
}
var P_N2O4 = [{t:'N'},{t:'2',k:'sub'},{t:'O'},{t:'4',k:'sub'}];
var P_NO2  = [{t:'NO'},{t:'2',k:'sub'}];
var P_KF   = [{t:'k',k:'it'},{t:'f',k:'sub'},{t:'[N'},{t:'2',k:'sub'},{t:'O'},{t:'4',k:'sub'},{t:']'}];
var P_KR   = [{t:'k',k:'it'},{t:'r',k:'sub'},{t:'[NO'},{t:'2',k:'sub'},{t:']'},{t:'2',k:'sup'}];

function hx(c){return [parseInt(c.substr(1,2),16),parseInt(c.substr(3,2),16),parseInt(c.substr(5,2),16)];}
function mixc(c1,c2,t){var a=hx(c1),b=hx(c2),r='#';for(var i=0;i<3;i++){var v=Math.round(a[i]+(b[i]-a[i])*t);r+=('0'+v.toString(16)).slice(-2);}return r;}

/* ─────────── kinetic model ─────────── */
var KF = 0.4, KR = 0.125, TMAX = 10, TEQ = 5.5, NSTEP = 1000, DT = TMAX / NSTEP;
var A0 = 1, tNow = 0, view = 'Concentration', motionOn = false;
var sim = [], cMax = 1.2, rMax = 0.48;

function simulate(a0) {
  var out = [{ t: 0, A: a0, B: 0 }], B = 0;
  var f = function (b) { return 2 * (KF * (a0 - b / 2) - KR * b * b); };
  for (var i = 1; i <= NSTEP; i++) {
    var k1 = f(B), k2 = f(B + DT * k1 / 2), k3 = f(B + DT * k2 / 2), k4 = f(B + DT * k3);
    B += DT * (k1 + 2 * k2 + 2 * k3 + k4) / 6;
    if (B < 0) B = 0;
    out.push({ t: i * DT, A: a0 - B / 2, B: B });
  }
  return out;
}
function stateAt(t) { var i = Math.round(t / DT); i = Math.max(0, Math.min(sim.length - 1, i)); return sim[i]; }

/* ─────────── gradients for atoms ─────────── */
var gradN = fdraw.gradient('radial', function (add) { add.stop(0, '#9db2e2'); add.stop(1, '#2d4884'); });
gradN.attr({ cx: 0.35, cy: 0.3, r: 0.8 });
var gradO = fdraw.gradient('radial', function (add) { add.stop(0, '#f4907f'); add.stop(1, '#a62b1b'); });
gradO.attr({ cx: 0.35, cy: 0.3, r: 0.8 });

/* ─────────── PANEL (a) ─────────── */
var gA = fdraw.group();
var FCY = 320, FR = 80, FLX = [118, 330, 540];
var SLOTS = [[-26,-46],[10,-46],[44,-46],[-56,-14],[-22,-14],[14,-14],[50,-14],
             [-50,18],[-16,18],[18,18],[52,18],[-28,48],[8,48],[40,48]];
var COMP = [
  { a: [0,1,4,5,6,7,8,9,11,12], b: [] },
  { a: [0,4,6,9,11], b: [1,2,3,5,7,8,10,12,13] },
  { a: [0,4,9,11], b: [1,2,3,5,6,7,8,10,12,13] }
];
var molecules = [], flaskHi = [], tubes = [];
var seed = 7;
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }

function mkN2O4(parent) {
  var g = parent.group();
  [[-13,-9],[-13,9],[13,-9],[13,9]].forEach(function (p) { g.circle(17).center(p[0], p[1]).fill(gradO); });
  g.circle(14).center(-6, 0).fill(gradN);
  g.circle(14).center(6, 0).fill(gradN);
  return g;
}
function mkNO2(parent) {
  var g = parent.group();
  g.circle(16).center(-10, 6).fill(gradO);
  g.circle(16).center(10, 6).fill(gradO);
  g.circle(13).center(0, -5).fill(gradN);
  return g;
}
function makeTube(cx, cy, rot, c1, c2) {
  var g = gA.group();
  var grad = fdraw.gradient('linear', function (add) { add.stop(0, '#ffffff'); add.stop(0.33, c1); add.stop(1, c2); });
  grad.from(0, 0).to(1, 1);
  g.path('M -11,-44 Q -11,-56 0,-56 Q 11,-56 11,-44 L 11,36 L 3,56 L -6,46 L -11,34 Z')
   .fill(grad).stroke({ color: 'rgba(0,0,0,0.13)', width: 1 });
  g.path('M -6,-46 L -6,28').fill('none').stroke({ color: '#ffffff', width: 3, opacity: 0.5 });
  g.attr('transform', 'translate(' + cx + ',' + cy + ') rotate(' + rot + ')');
  return { g: g, grad: grad };
}
function calloutArrow(cx) {
  gA.path('M ' + (cx-50) + ',168 C ' + (cx-58) + ',196 ' + (cx-40) + ',206 ' + (cx-22) + ',208 ' +
          'L ' + (cx-22) + ',197 L ' + (cx-2) + ',218 L ' + (cx-22) + ',239 L ' + (cx-22) + ',228 ' +
          'C ' + (cx-36) + ',226 ' + (cx-42) + ',210 ' + (cx-40) + ',168 Z')
    .fill('#c6c6c6').stroke({ color: '#b0b0b0', width: 1 });
}

var TIPS = [
  ['t = 0 : pure N₂O₄', 'Only N₂O₄ molecules are present and the gas is colourless. The forward rate kf[N₂O₄] is at its maximum, while the reverse rate is exactly zero because [NO₂] = 0.'],
  ['Pre-equilibrium', 'N₂O₄ molecules are splitting into pairs of NO₂. The brown colour deepens as [NO₂] grows, the forward rate falls and the reverse rate climbs — they have not met yet.'],
  ['At equilibrium', 'Forward and reverse rates are now equal, so the number of each kind of molecule stays constant. The molecules keep dissociating and recombining: equilibrium is dynamic, not static.']
];
var TUBEC = [['#f2f4fd', '#c6d2ef'], ['#f8dd96', '#dda63b'], ['#ef9c4e', '#c5561c']];

for (var fi = 0; fi < 3; fi++) {
  var cx = FLX[fi];
  txt(gA, cx, 30, ['t = 0', 'pre-equilibrium', 'at equilibrium'][fi], 16.5);
  tubes.push(makeTube(cx - 6, 118, -35, TUBEC[fi][0], TUBEC[fi][1]));
  calloutArrow(cx);
  var hi = gA.circle((FR + 9) * 2).center(cx, FCY).fill('none').stroke({ color: '#e8a838', width: 5 }).opacity(0);
  flaskHi.push(hi);
  gA.circle(FR * 2).center(cx, FCY).fill('#ffffff').stroke({ color: GRAY, width: 3 });
  var mg = gA.group();
  (function (idx, mg, cx) {
    var c = COMP[idx];
    c.a.forEach(function (s) { addMol(mg, cx, SLOTS[s], 'a'); });
    c.b.forEach(function (s) { addMol(mg, cx, SLOTS[s], 'b'); });
  })(fi, mg, cx);
  var hit = gA.circle(FR * 2).center(cx, FCY).fill('#fff').opacity(0).css('cursor', 'pointer');
  (function (i) {
    hit.on('mousemove', function (e) { showTooltip(TIPS[i][0], e); })
       .on('mouseleave', hideTooltip)
       .on('click', function () { showPopup(TIPS[i][0], TIPS[i][1]); });
  })(fi);
}
function addMol(mg, cx, s, kind) {
  var jx = (rnd() - 0.5) * 6, jy = (rnd() - 0.5) * 6, rot = (rnd() - 0.5) * 60;
  var g = (kind === 'a') ? mkN2O4(mg) : mkNO2(mg);
  var m = { g: g, fcx: cx, fcy: FCY, bx: s[0] + jx, by: s[1] + jy, ox: 0, oy: 0, rot: rot,
            vx: (rnd() - 0.5) * 0.7, vy: (rnd() - 0.5) * 0.7, vr: (rnd() - 0.5) * 0.9 };
  g.attr('transform', 'translate(' + (m.fcx + m.bx) + ',' + (m.fcy + m.by) + ') rotate(' + m.rot + ')');
  molecules.push(m);
}

