/* ─────────── plot geometry ─────────── */
var BX0 = 95, BX1 = 600, BYT = 530, BYB = 800;
var CX0 = 95, CX1 = 600, CYT = 930, CYB = 1195;
function bxAt(t) { return BX0 + (t / TMAX) * (BX1 - BX0); }
function byAt(v) { return BYB - (v / cMax) * (BYB - BYT); }
function cyAt(v) { return CYB - (v / rMax) * (CYB - CYT); }

var gB = fdraw.group(), gC = fdraw.group();
var hitB = gB.rect(BX1 - BX0 + 50, BYB - BYT + 40).move(BX0 - 10, BYT - 20).fill('#fff').opacity(0).css('cursor', 'ew-resize');
var gBDyn = gB.group(), gBAx = gB.group(), gBMark = gB.group();
var hitC = gC.rect(CX1 - CX0 + 50, CYB - CYT + 40).move(CX0 - 10, CYT - 20).fill('#fff').opacity(0).css('cursor', 'ew-resize');
var gCDyn = gC.group(), gCAx = gC.group(), gCMark = gC.group();

function drawAxes(g, x0, x1, yT, yB) {
  g.line(x0, yB, x1 + 30, yB).stroke({ color: '#000', width: 2.5 });
  g.polygon((x1 + 44) + ',' + yB + ' ' + (x1 + 29) + ',' + (yB - 6.5) + ' ' + (x1 + 29) + ',' + (yB + 6.5)).fill('#000');
  g.line(x0, yB, x0, yT - 16).stroke({ color: '#000', width: 2.5 });
  g.polygon(x0 + ',' + (yT - 30) + ' ' + (x0 - 6.5) + ',' + (yT - 15) + ' ' + (x0 + 6.5) + ',' + (yT - 15)).fill('#000');
}
drawAxes(gBAx, BX0, BX1, BYT, BYB);
txt(gBAx, 52, (BYT + BYB) / 2, 'Concentration', 16).attr('transform', 'rotate(-90 52 ' + ((BYT + BYB) / 2) + ')');
txt(gBAx, BX0 - 14, BYB + 22, '0', 15);
txt(gBAx, 373, BYB + 28, 'Time', 16);
txt(gBAx, 348, 866, '(b)', 16);
drawAxes(gCAx, CX0, CX1, CYT, CYB);
txt(gCAx, 52, (CYT + CYB) / 2, 'Rate', 16).attr('transform', 'rotate(-90 52 ' + ((CYT + CYB) / 2) + ')');
txt(gCAx, CX0 - 14, CYB + 22, '0', 15);
txt(gCAx, 373, CYB + 28, 'Time', 16);
txt(gCAx, 348, 1258, '(c)', 16);

/* ─────────── readout card ─────────── */
var card = fdraw.group();
card.rect(256, 106).move(398, 810).radius(6).fill('#ffffff').stroke({ color: '#cfd4da', width: 1 });
var rdTitle = txt(card, 412, 830, 't = 0.0', 12.5, { anchor: 'start', weight: 'bold' });
var rdStatus = txt(card, 644, 830, '', 10.5, { anchor: 'end', fill: '#8a5a00' });
var gConcRow = card.group(), gRateRow = card.group();
chem(gConcRow, 412, 852, 11.5, P_N2O4.concat([{ t: ' =' }]), { fill: BLUE });
chem(gConcRow, 412, 870, 11.5, P_NO2.concat([{ t: ' =' }]), { fill: RED });
var rdA = txt(gConcRow, 644, 852, '', 11.5, { anchor: 'end', fill: BLUE });
var rdB = txt(gConcRow, 644, 870, '', 11.5, { anchor: 'end', fill: RED });
chem(gRateRow, 412, 892, 11.5, P_KF.concat([{ t: ' =' }]), { fill: BLUE });
chem(gRateRow, 412, 910, 11.5, P_KR.concat([{ t: ' =' }]), { fill: RED });
var rdF = txt(gRateRow, 644, 892, '', 11.5, { anchor: 'end', fill: BLUE });
var rdR = txt(gRateRow, 644, 910, '', 11.5, { anchor: 'end', fill: RED });
card.on('mousemove', function (e) { showTooltip('Values at the marked instant', e); }).on('mouseleave', hideTooltip);
card.css('cursor', 'pointer').on('click', function () {
  showPopup('Reading one instant', 'Every row is the same instant in time. Equilibrium is announced by the two rate rows becoming equal — and that is precisely when the two concentration rows stop changing.');
});

/* ─────────── marker elements ─────────── */
var mBLine = gBMark.line(BX0, BYB, BX0, BYT).stroke({ color: '#333', width: 1.8, dasharray: '3,3' });
var mBdotA = gBMark.circle(10).fill(BLUE).stroke({ color: '#fff', width: 2 });
var mBdotB = gBMark.circle(10).fill(RED).stroke({ color: '#fff', width: 2 });
var mBhand = gBMark.polygon('0,0 -7,13 7,13').fill('#333');
var mCLine = gCMark.line(CX0, CYB, CX0, CYT).stroke({ color: '#333', width: 1.8, dasharray: '3,3' });
var mCdotF = gCMark.circle(10).fill(BLUE).stroke({ color: '#fff', width: 2 });
var mCdotR = gCMark.circle(10).fill(RED).stroke({ color: '#fff', width: 2 });
var mChand = gCMark.polygon('0,0 -7,13 7,13').fill('#333');

/* ─────────── render plots ─────────── */
function ptsOf(sel, xf, yf) {
  var s = [];
  for (var i = 0; i < sim.length; i += 5) s.push(xf(sim[i].t) + ',' + yf(sel(sim[i])));
  return s.join(' ');
}
function renderPlots() {
  sim = simulate(A0);
  var last = sim[sim.length - 1];
  cMax = 1.2 * Math.max(A0, last.B);
  rMax = 1.2 * KF * A0;
  gBDyn.clear(); gCDyn.clear();
  var dashX = bxAt(TEQ);

  /* (b) */
  var topB = byAt(last.B);
  var shB = gBDyn.rect(BX1 - dashX, BYB - topB).move(dashX, topB).fill(YEL);
  gBDyn.polyline(ptsOf(function (s) { return s.B; }, bxAt, byAt)).fill('none')
    .stroke({ color: RED, width: 3.2, linecap: 'round', linejoin: 'round' });
  gBDyn.polyline(ptsOf(function (s) { return s.A; }, bxAt, byAt)).fill('none')
    .stroke({ color: BLUE, width: 3.2, linecap: 'round', linejoin: 'round' });
  gBDyn.line(dashX, BYB, dashX, topB).stroke({ color: '#000', width: 2, dasharray: '9,7' });
  txt(gBDyn, (dashX + BX1) / 2, topB + 48, 'Equilibrium', 16, { halo: true });
  txt(gBDyn, (dashX + BX1) / 2, topB + 70, 'achieved', 16, { halo: true });
  chem(gBDyn, 246, byAt(stateAt(3).B) - 14, 16, P_NO2, { halo: true });
  chem(gBDyn, 246, byAt(stateAt(3).A) + 28, 16, P_N2O4, { halo: true });

  /* (c) */
  var rEq = KF * last.A, topC = cyAt(rEq);
  gCDyn.rect(CX1 - dashX, CYB - topC).move(dashX, topC).fill(YEL);
  gCDyn.polyline(ptsOf(function (s) { return KR * s.B * s.B; }, bxAt, cyAt)).fill('none')
    .stroke({ color: RED, width: 3.2, linecap: 'round', linejoin: 'round' });
  gCDyn.polyline(ptsOf(function (s) { return KF * s.A; }, bxAt, cyAt)).fill('none')
    .stroke({ color: BLUE, width: 3.2, linecap: 'round', linejoin: 'round' });
  gCDyn.line(dashX, CYB, dashX, topC).stroke({ color: '#000', width: 2, dasharray: '9,7' });
  txt(gCDyn, (dashX + CX1) / 2, topC + 42, 'Equilibrium', 16, { halo: true });
  txt(gCDyn, (dashX + CX1) / 2, topC + 64, 'achieved', 16, { halo: true });
  chem(gCDyn, 150, cyAt(KF * stateAt(0.9).A) - 16, 15.5, P_KF, { halo: true });
  chem(gCDyn, 150, cyAt(KR * stateAt(2.2).B * stateAt(2.2).B) + 30, 15.5, P_KR, { halo: true });

  /* hover / click zones */
  var hz = function (el, tip, title, body) {
    el.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(title, body); });
  };
  hz(shB, 'Equilibrium region', 'Equilibrium achieved',
     'To the right of the dashed line the concentrations are flat and, in panel (c), the two rate curves lie on top of each other. The flat concentrations are a consequence of the equal rates.');
  renderMarker();
}

/* ─────────── marker / readout ─────────── */
function renderMarker() {
  var s = stateAt(tNow);
  var x = bxAt(tNow);
  var rf = KF * s.A, rr = KR * s.B * s.B;

  var topB = Math.min(byAt(s.A), byAt(s.B)) - 16;
  mBLine.plot(x, BYB, x, Math.max(BYT - 6, topB));
  mBdotA.center(x, byAt(s.A)); mBdotB.center(x, byAt(s.B));
  mBhand.attr('transform', 'translate(' + x + ',' + (BYB + 2) + ')');

  var topC = Math.min(cyAt(rf), cyAt(rr)) - 16;
  mCLine.plot(x, CYB, x, Math.max(CYT - 6, topC));
  mCdotF.center(x, cyAt(rf)); mCdotR.center(x, cyAt(rr));
  mChand.attr('transform', 'translate(' + x + ',' + (CYB + 2) + ')');

  rdTitle.text('t = ' + tNow.toFixed(1));
  rdA.text(s.A.toFixed(2) + ' M');
  rdB.text(s.B.toFixed(2) + ' M');
  rdF.text(rf.toFixed(3));
  rdR.text(rr.toFixed(3));
  var eq = rf > 0 && Math.abs(rf - rr) / rf < 0.03;
  rdStatus.text(eq ? 'rates equal → equilibrium' : 'rates unequal → still changing');
  rdStatus.fill(eq ? '#2e7d32' : '#8a5a00');

  var hiIdx = (tNow < 0.6) ? 0 : (tNow < TEQ ? 1 : 2);
  for (var i = 0; i < 3; i++) flaskHi[i].opacity(i === hiIdx ? 0.95 : 0);
}

/* ─────────── tube colour with A0 ─────────── */
function updateTubes() {
  var u = (A0 - 0.2) / 1.8;
  tubes[1].grad.update(function (add) {
    add.stop(0, '#ffffff'); add.stop(0.33, mixc('#fbe9b8', '#f3c765', u)); add.stop(1, mixc('#e9c069', '#d98f28', u));
  });
  tubes[1].grad.from(0, 0).to(1, 1);
  tubes[2].grad.update(function (add) {
    add.stop(0, '#ffffff'); add.stop(0.33, mixc('#f5c48f', '#e08a3c', u)); add.stop(1, mixc('#d98c46', '#a8410f', u));
  });
  tubes[2].grad.from(0, 0).to(1, 1);
}

/* ─────────── interactions ─────────── */
function update_timeMarker(v) { tNow = Math.max(0, Math.min(TMAX, v)); renderMarker(); }
function update_initialN2O4(v) { A0 = v; renderPlots(); updateTubes(); }
function toggle_panelView(v) {
  view = v;
  gB.opacity(v === 'Rate' ? 0.9 : 1);
  gC.opacity(v === 'Concentration' ? 0.9 : 1);
  var cOn = (v !== 'Rate'), rOn = (v !== 'Concentration');
  gConcRow.opacity(cOn ? 1 : 0.4);
  gRateRow.opacity(rOn ? 1 : 0.4);
  [mBdotA, mBdotB].forEach(function (d) { d.radius(cOn ? 5 : 3.2); });
  [mCdotF, mCdotR].forEach(function (d) { d.radius(rOn ? 5 : 3.2); });
  mBLine.stroke({ width: cOn ? 1.9 : 1 });
  mCLine.stroke({ width: rOn ? 1.9 : 1 });
  renderMarker();
}
var motionRAF = null;
function toggle_moleculeMotion(on) {
  motionOn = on;
  if (on && !motionRAF) motionRAF = requestAnimationFrame(motionStep);
  if (!on && motionRAF) {
    cancelAnimationFrame(motionRAF); motionRAF = null;
    molecules.forEach(function (m) {
      m.ox = 0; m.oy = 0;
      m.g.attr('transform', 'translate(' + (m.fcx + m.bx) + ',' + (m.fcy + m.by) + ') rotate(' + m.rot + ')');
    });
  }
}
function motionStep() {
  var lim = FR - 20;
  for (var i = 0; i < molecules.length; i++) {
    var m = molecules[i];
    m.ox += m.vx; m.oy += m.vy; m.rot += m.vr;
    var dx = m.bx + m.ox, dy = m.by + m.oy, d = Math.sqrt(dx * dx + dy * dy);
    if (d > lim && (m.vx * dx + m.vy * dy) > 0) {
      var nx = dx / d, ny = dy / d, dot = m.vx * nx + m.vy * ny;
      m.vx -= 2 * dot * nx; m.vy -= 2 * dot * ny;
    }
    m.g.attr('transform', 'translate(' + (m.fcx + m.bx + m.ox) + ',' + (m.fcy + m.by + m.oy) + ') rotate(' + m.rot + ')');
  }
  motionRAF = requestAnimationFrame(motionStep);
}

/* ─────────── dragging the marker ─────────── */
function toUser(e) {
  var r = fdraw.node.getBoundingClientRect();
  var sc = Math.min(r.width / FW, r.height / FH);
  var ox = (r.width - FW * sc) / 2, oy = (r.height - FH * sc) / 2;
  return { x: (e.clientX - r.left - ox) / sc, y: (e.clientY - r.top - oy) / sc };
}
var dragging = false;
function dragTo(e) {
  var p = toUser(e);
  var t = (p.x - BX0) / (BX1 - BX0) * TMAX;
  t = Math.max(0, Math.min(TMAX, t));
  setInput('timeMarker', t.toFixed(1));
  update_timeMarker(t);
}
function startDrag(e) { dragging = true; dragTo(e); if (e.preventDefault) e.preventDefault(); }
gB.on('mousedown', startDrag);
gC.on('mousedown', startDrag);
