function stateAt(t) { var i = Math.round(t / DT); i = Math.max(0, Math.min(sim.length - 1, i)); return sim[i]; }
function rfOf(s) { return KF * s.A; }
function rrOf(s) { return KR * s.B * s.B; }
/* first instant at which the two rates agree to within 2 % */
function computeTeq() {
  for (var i = 1; i < sim.length; i++) {
    var s = sim[i], rf = rfOf(s), rr = rrOf(s);
    if (rf > 1e-9 && Math.abs(rf - rr) / rf < 0.02) return Math.max(1.5, Math.min(8.8, s.t));
  }
  return 8.8;
}

/* ─────────── gradients for atoms ─────────── */
var gradN = fdraw.gradient('radial', function (add) { add.stop(0, '#9db2e2'); add.stop(1, '#2d4884'); });
gradN.attr({ cx: 0.35, cy: 0.3, r: 0.8 });
var gradO = fdraw.gradient('radial', function (add) { add.stop(0, '#f4907f'); add.stop(1, '#a62b1b'); });
gradO.attr({ cx: 0.35, cy: 0.3, r: 0.8 });

/* ─────────── PANEL (a) ─────────── */
var gA = fdraw.group();
var FCY = 250, FR = 78, RPLACE = 52, FLX = [115, 330, 545];
var molecules = [], flaskHalo = [], tubes = [];
var seed = 11;
function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }

/* dumbbell N2O4: two joined blue N, each carrying two red O */
function mkN2O4(parent) {
  var g = parent.group();
  [[-14,-8],[-14,8],[14,-8],[14,8]].forEach(function (p) { g.circle(22).center(p[0], p[1]).fill(gradO); });
  g.circle(20).center(-6, 0).fill(gradN);
  g.circle(20).center(6, 0).fill(gradN);
  return g;
}
/* bent NO2: single blue N with two red O */
function mkNO2(parent) {
  var g = parent.group();
  g.circle(22).center(-10, 5).fill(gradO);
  g.circle(22).center(10, 5).fill(gradO);
  g.circle(20).center(0, -4).fill(gradN);
  return g;
}
function placePoints(n, Rp, minD) {
  var pts = [], tries = 0;
  while (pts.length < n && tries < 6000) {
    tries++;
    var a = rnd() * Math.PI * 2, r = Math.sqrt(rnd()) * Rp;
    var x = Math.cos(a) * r, y = Math.sin(a) * r, ok = true;
    for (var i = 0; i < pts.length; i++) {
      var dx = pts[i][0] - x, dy = pts[i][1] - y;
      if (dx * dx + dy * dy < minD * minD) { ok = false; break; }
    }
    if (ok) pts.push([x, y]);
    if (tries % 700 === 0) minD *= 0.9;
  }
  return pts;
}
function makeTube(cx, cy, rot, c1, c2) {
  var g = gA.group();
  var grad = fdraw.gradient('linear', function (add) { add.stop(0, '#ffffff'); add.stop(0.33, c1); add.stop(1, c2); });
  grad.from(0, 0).to(1, 1);
  g.path('M -11,-44 Q -11,-56 0,-56 Q 11,-56 11,-44 L 11,36 L 3,56 L -6,46 L -11,34 Z')
   .fill(grad).stroke({ color: 'rgba(0,0,0,0.13)', width: 1 });
  g.path('M -6,-46 L -6,28').fill('none').stroke({ color: '#ffffff', width: 3, opacity: 0.5 });
  g.attr('transform', 'translate(' + cx + ',' + cy + ') rotate(' + rot + ') scale(0.88)');
  return { g: g, grad: grad };
}
function calloutArrow(cx) {
  var g = gA.group();
  g.path('M -50,0 C -58,28 -40,38 -22,40 L -22,29 L -2,50 L -22,71 L -22,60 C -36,58 -42,42 -40,0 Z')
   .fill('#c6c6c6').stroke({ color: '#b0b0b0', width: 1 });
  g.attr('transform', 'translate(' + cx + ',122) scale(0.72)');
}

var TIPS = [
  ['t = 0 : pure N₂O₄', 'Only N₂O₄ molecules are present and the gas is colourless. The forward rate kf[N₂O₄] is at its maximum, while the reverse rate is exactly zero because [NO₂] = 0.'],
  ['Pre-equilibrium', 'N₂O₄ molecules are splitting into pairs of NO₂. The brown colour deepens as [NO₂] grows, the forward rate falls and the reverse rate climbs — they have not met yet.'],
  ['At equilibrium', 'Forward and reverse rates are now equal, so the number of each kind of molecule stays constant. The molecules keep dissociating and recombining: equilibrium is dynamic, not static.']
];
var TUBEC = [['#f2f4fd', '#c6d2ef'], ['#f8dd96', '#dda63b'], ['#ef9c4e', '#c5561c']];
var COUNTS = [[9, 0], [5, 8], [4, 10]];

for (var fi = 0; fi < 3; fi++) {
  var cx = FLX[fi];
  txt(gA, cx, 28, ['t = 0', 'pre-equilibrium', 'at equilibrium'][fi], 24);
  tubes.push(makeTube(cx - 4, 92, -35, TUBEC[fi][0], TUBEC[fi][1]));
  calloutArrow(cx);
  var halo = gA.circle((FR + 11) * 2).center(cx, FCY).fill(YEL).opacity(0);
  flaskHalo.push(halo);
  gA.circle(FR * 2).center(cx, FCY).fill('#ffffff').stroke({ color: GRAY, width: 3.4 });
  var mg = gA.group();
  (function (idx, mg, cx) {
    var n = COUNTS[idx][0] + COUNTS[idx][1];
    var pts = placePoints(n, RPLACE, 34);
    for (var i = 0; i < pts.length; i++) {
      addMol(mg, cx, pts[i], i < COUNTS[idx][0] ? 'a' : 'b');
    }
  })(fi, mg, cx);
  var hit = gA.circle(FR * 2).center(cx, FCY).fill('#fff').opacity(0).css('cursor', 'pointer');
  (function (i) {
    hit.on('mousemove', function (e) { showTooltip(TIPS[i][0], e); })
       .on('mouseleave', hideTooltip)
       .on('click', function () { showPopup(TIPS[i][0], TIPS[i][1]); });
  })(fi);
}
function addMol(mg, cx, s, kind) {
  var rot = (rnd() - 0.5) * 120;
  var g = (kind === 'a') ? mkN2O4(mg) : mkNO2(mg);
  var m = { g: g, fcx: cx, fcy: FCY, bx: s[0], by: s[1], ox: 0, oy: 0, rot: rot,
            vx: (rnd() - 0.5) * 0.8, vy: (rnd() - 0.5) * 0.8, vr: (rnd() - 0.5) * 1.1 };
  g.attr('transform', 'translate(' + (m.fcx + m.bx) + ',' + (m.fcy + m.by) + ') rotate(' + m.rot + ')');
  molecules.push(m);
}

/* leader labels for (a) */
gA.line(86, 298, 150, 342).stroke({ color: '#000', width: 2.4 });
chem(gA, 156, 352, 24, P_N2O4);
gA.line(302, 300, 372, 342).stroke({ color: '#000', width: 2.4 });
chem(gA, 378, 352, 24, P_NO2);
txt(gA, 330, 394, '(a)', 24);

/* ─────────── plot geometry ─────────── */
var BX0 = 100, BX1 = 590, BYT = 448, BYB = 658;
var CX0 = 100, CX1 = 590, CYT = 765, CYB = 958;
function bxAt(t) { return BX0 + (t / TMAX) * (BX1 - BX0); }
function byAt(v) { return BYB - (v / cMax) * (BYB - BYT); }
function cyAt(v) { return CYB - (v / rMax) * (CYB - CYT); }

var gB = fdraw.group(), gC = fdraw.group();
gB.rect(BX1 - BX0 + 60, BYB - BYT + 60).move(BX0 - 12, BYT - 30).fill('#fff').opacity(0).css('cursor', 'ew-resize');
var gBDyn = gB.group(), gBAx = gB.group(), gBMark = gB.group();
gC.rect(CX1 - CX0 + 60, CYB - CYT + 60).move(CX0 - 12, CYT - 30).fill('#fff').opacity(0).css('cursor', 'ew-resize');
var gCDyn = gC.group(), gCAx = gC.group(), gCMark = gC.group();

function drawAxes(g, x0, x1, yT, yB) {
  g.line(x0, yB, x1 + 28, yB).stroke({ color: '#000', width: 3 });
  g.polygon((x1 + 44) + ',' + yB + ' ' + (x1 + 27) + ',' + (yB - 8) + ' ' + (x1 + 27) + ',' + (yB + 8)).fill('#000');
  g.line(x0, yB, x0, yT - 14).stroke({ color: '#000', width: 3 });
  g.polygon(x0 + ',' + (yT - 30) + ' ' + (x0 - 8) + ',' + (yT - 13) + ' ' + (x0 + 8) + ',' + (yT - 13)).fill('#000');
}
drawAxes(gBAx, BX0, BX1, BYT, BYB);
txt(gBAx, 44, (BYT + BYB) / 2, 'Concentration', 24).attr('transform', 'rotate(-90 44 ' + ((BYT + BYB) / 2) + ')');
txt(gBAx, BX0 - 18, BYB + 26, '0', 22);
txt(gBAx, 352, BYB + 34, 'Time', 24);
txt(gBAx, 330, 722, '(b)', 24);
drawAxes(gCAx, CX0, CX1, CYT, CYB);
txt(gCAx, 44, (CYT + CYB) / 2, 'Rate', 24).attr('transform', 'rotate(-90 44 ' + ((CYT + CYB) / 2) + ')');
txt(gCAx, CX0 - 18, CYB + 26, '0', 22);
txt(gCAx, 352, CYB + 34, 'Time', 24);
txt(gCAx, 330, 1022, '(c)', 24);

/* ─────────── marker elements ─────────── */
var mBLine = gBMark.line(BX0, BYB, BX0, BYT).stroke({ color: '#333', width: 2, dasharray: '4,4' });
var mBdotA = gBMark.circle(13).fill(BLUE).stroke({ color: '#fff', width: 2.4 });
var mBdotB = gBMark.circle(13).fill(RED).stroke({ color: '#fff', width: 2.4 });
var mBhand = gBMark.polygon('0,0 -9,16 9,16').fill('#333');
var mCLine = gCMark.line(CX0, CYB, CX0, CYT).stroke({ color: '#333', width: 2, dasharray: '4,4' });
var mCdotF = gCMark.circle(13).fill(BLUE).stroke({ color: '#fff', width: 2.4 });
var mCdotR = gCMark.circle(13).fill(RED).stroke({ color: '#fff', width: 2.4 });
var mChand = gCMark.polygon('0,0 -9,16 9,16').fill('#333');

/* ─────────── render plots ─────────── */
function ptsOf(sel, xf, yf) {
  var s = [];
  for (var i = 0; i < sim.length; i += 5) s.push(xf(sim[i].t) + ',' + yf(sel(sim[i])));
  return s.join(' ');
}
function bandText(g, xc, top, bottom) {
  var h = bottom - top;
  var f = Math.max(15, Math.min(24, (h - 14) / 2.15));
  var gap = f * 1.1;
  var cy = (top + bottom) / 2;
  txt(g, xc, cy - gap * 0.18, 'Equilibrium', f, { halo: true });
  txt(g, xc, cy - gap * 0.18 + gap, 'achieved', f, { halo: true });
}
function renderPlots() {
  sim = simulate(A0);
  TEQ = computeTeq();
  var last = sim[sim.length - 1];
  cMax = 1.2 * Math.max(A0, last.B);
  rMax = (KF * A0) / 0.9;
  gBDyn.clear(); gCDyn.clear();
  var dashX = bxAt(TEQ);

  /* (b) concentration */
  var topB = byAt(last.B);
  var shB = gBDyn.rect(BX1 - dashX, BYB - topB).move(dashX, topB).fill(YEL);
  gBDyn.polyline(ptsOf(function (s) { return s.B; }, bxAt, byAt)).fill('none')
    .stroke({ color: RED, width: 3.6, linecap: 'round', linejoin: 'round' });
  gBDyn.polyline(ptsOf(function (s) { return s.A; }, bxAt, byAt)).fill('none')
    .stroke({ color: BLUE, width: 3.6, linecap: 'round', linejoin: 'round' });
  gBDyn.line(dashX, BYB, dashX, topB).stroke({ color: '#000', width: 2.4, dasharray: '10,8' });
  bandText(gBDyn, (dashX + BX1) / 2, topB, BYB);
  var s3 = stateAt(Math.min(3, TEQ * 0.6));
  chem(gBDyn, bxAt(Math.min(3, TEQ * 0.6)) - 10, byAt(s3.B) - 14, 23, P_NO2, { halo: true, anchor: 'middle' });
  chem(gBDyn, bxAt(Math.min(3, TEQ * 0.6)) - 10, byAt(s3.A) + 34, 23, P_N2O4, { halo: true, anchor: 'middle' });

  /* (c) rates */
  var rEq = rfOf(last), topC = cyAt(rEq);
  var shC = gCDyn.rect(CX1 - dashX, CYB - topC).move(dashX, topC).fill(YEL);
  gCDyn.polyline(ptsOf(rrOf, bxAt, cyAt)).fill('none')
    .stroke({ color: RED, width: 3.6, linecap: 'round', linejoin: 'round' });
  gCDyn.polyline(ptsOf(rfOf, bxAt, cyAt)).fill('none')
    .stroke({ color: BLUE, width: 3.6, linecap: 'round', linejoin: 'round' });
  gCDyn.line(dashX, CYB, dashX, topC).stroke({ color: '#000', width: 2.4, dasharray: '10,8' });
  bandText(gCDyn, (dashX + CX1) / 2, topC, CYB);
  var tf = TEQ * 0.28, tr = TEQ * 0.46;
  chem(gCDyn, bxAt(tf) + 8, cyAt(rfOf(stateAt(tf))) - 14, 22, P_KF, { halo: true });
  chem(gCDyn, bxAt(tr) + 8, cyAt(rrOf(stateAt(tr))) + 34, 22, P_KR, { halo: true });

  var hz = function (el, tip, title, body) {
    el.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
      .on('click', function () { showPopup(title, body); });
  };
  hz(shB, 'Equilibrium achieved (t ≳ ' + TEQ.toFixed(1) + ')', 'Equilibrium achieved',
     'To the right of the dashed line the concentrations are flat and, in panel (c), the two rate curves lie on top of each other. The flat concentrations are a consequence of the equal rates.');
  hz(shC, 'Rates equal from t ≈ ' + TEQ.toFixed(1), 'Why the plateau happens here',
     'The dashed line is computed from the simulation: it is the first instant where the forward and reverse rates agree to within 2 %. Change the initial [N₂O₄] and the line moves, because a faster start reaches equal rates sooner.');
  var el = document.getElementById('roTeq');
  if (el) el.textContent = 'equilibrium at t ≈ ' + TEQ.toFixed(1);
  renderMarker();
}

/* ─────────── marker / readout ─────────── */
function renderMarker() {
  var s = stateAt(tNow);
  var x = bxAt(tNow);
  var rf = rfOf(s), rr = rrOf(s);

  var topB = Math.min(byAt(s.A), byAt(s.B)) - 18;
  mBLine.plot(x, BYB, x, Math.max(BYT - 6, topB));
  mBdotA.center(x, byAt(s.A)); mBdotB.center(x, byAt(s.B));
  mBhand.attr('transform', 'translate(' + x + ',' + (BYB + 3) + ')');

  var topC = Math.min(cyAt(rf), cyAt(rr)) - 18;
  mCLine.plot(x, CYB, x, Math.max(CYT - 6, topC));
  mCdotF.center(x, cyAt(rf)); mCdotR.center(x, cyAt(rr));
  mChand.attr('transform', 'translate(' + x + ',' + (CYB + 3) + ')');

  var set = function (id, v) { var e = document.getElementById(id); if (e) e.textContent = v; };
  set('roT', 't = ' + tNow.toFixed(1));
  set('roA', s.A.toFixed(2));
  set('roB', s.B.toFixed(2));
  set('roF', rf.toFixed(3));
  set('roR', rr.toFixed(3));
  var eq = rf > 0 && Math.abs(rf - rr) / rf < 0.02;
  var st = document.getElementById('roStatus');
  if (st) {
    st.textContent = eq ? 'rates equal → equilibrium' : 'rates unequal → still changing';
    st.style.color = eq ? '#2e7d32' : '#8a5a00';
  }

  /* soft halo: hidden in the default (t = 0) state so it matches the printed figure */
  var hiIdx = (tNow < TEQ * 0.35) ? 0 : (tNow < TEQ ? 1 : 2);
  for (var i = 0; i < 3; i++) flaskHalo[i].opacity((tNow > 0.05 && i === hiIdx) ? 0.85 : 0);
}

/* ─────────── tube colour with A0 ─────────── */
function updateTubes() {
  var u = (A0 - 0.2) / 1.8;
  tubes[1].grad.update(function (add) {
    add.stop(0, '#ffffff'); add.stop(0.33, mixc('#fbe9b8', '#f3c765', u)); add.stop(1, mixc('#e9c069', '#d98f28', u));
  });
  tubes[1].grad.from(0, 0).to(1, 1);
  tubes[2].grad.update(function (add) {
    add.stop(0, '#ffffff'); add.stop(0.33, mixc('#f5c48f', '#e08a3c', u)); add.stop(1, mixc('#d98c46', '#a8410f', u));
  });
  tubes[2].grad.from(0, 0).to(1, 1);
}

/* ─────────── interactions ─────────── */
function update_timeMarker(v) { tNow = Math.max(0, Math.min(TMAX, v)); renderMarker(); }
function update_initialN2O4(v) { A0 = v; renderPlots(); updateTubes(); }
function toggle_panelView(v) {
  view = v;
  gB.opacity(v === 'Rate' ? 0.28 : 1);
  gC.opacity(v === 'Concentration' ? 0.28 : 1);
}
var motionRAF = null;
function toggle_moleculeMotion(on) {
  motionOn = on;
  if (on && !motionRAF) motionRAF = requestAnimationFrame(motionStep);
  if (!on && motionRAF) {
    cancelAnimationFrame(motionRAF); motionRAF = null;
    molecules.forEach(function (m) {
      m.ox = 0; m.oy = 0;
      m.g.attr('transform', 'translate(' + (m.fcx + m.bx) + ',' + (m.fcy + m.by) + ') rotate(' + m.rot + ')');
    });
  }
}
function motionStep() {
  var lim = RPLACE + 2;
  for (var i = 0; i < molecules.length; i++) {
    var m = molecules[i];
    m.ox += m.vx; m.oy += m.vy; m.rot += m.vr;
    var dx = m.bx + m.ox, dy = m.by + m.oy, d = Math.sqrt(dx * dx + dy * dy) || 1;
    if (d > lim && (m.vx * dx + m.vy * dy) > 0) {
      var nx = dx / d, ny = dy / d, dot = m.vx * nx + m.vy * ny;
      m.vx -= 2 * dot * nx; m.vy -= 2 * dot * ny;
    }
    m.g.attr('transform', 'translate(' + (m.fcx + m.bx + m.ox) + ',' + (m.fcy + m.by + m.oy) + ') rotate(' + m.rot + ')');
  }
  motionRAF = requestAnimationFrame(motionStep);
}

/* ─────────── dragging the marker ─────────── */
function toUser(e) {
  var r = fdraw.node.getBoundingClientRect();
  var sc = Math.min(r.width / FW, r.height / FH);
  var ox = (r.width - FW * sc) / 2, oy = (r.height - FH * sc) / 2;
  return { x: (e.clientX - r.left - ox) / sc, y: (e.clientY - r.top - oy) / sc };
}
var dragging = false;
function dragTo(e) {
  var p = toUser(e);
  var t = (p.x - BX0) / (BX1 - BX0) * TMAX;
  t = Math.max(0, Math.min(TMAX, t));
  setInput('timeMarker', t.toFixed(1));
  update_timeMarker(t);
}
function startDrag(e) { dragging = true; dragTo(e); if (e.preventDefault) e.preventDefault(); }
gB.on('mousedown', startDrag);
gC.on('mousedown', startDrag);
document.addEventListener('mousemove', function (e) { if (dragging) dragTo(e); });
document.addEventListener('mouseup', function () { dragging = false; });

/* ─────────── demo steps ─────────── */
var DEMO = [
  { title: 't = 0: pure N₂O₄',
    narration: 'The flask holds only dumbbell-shaped N₂O₄ molecules and the gas is colourless. [NO₂] is zero, so the reverse rate is zero while the forward rate is at its maximum.',
    state: { timeMarker: 0, panelView: 'Both', initialN2O4: 1, motion: false } },
  { title: 'Pre-equilibrium: the reaction runs',
    narration: 'Move the time marker forward. N₂O₄ is consumed, bent brown NO₂ molecules appear and the gas darkens; the blue concentration curve falls as the red one climbs.',
    state: { timeMarker: 2, panelView: 'Concentration', initialN2O4: 1, motion: false } },
  { title: 'Watch the rates instead',
    narration: 'Emphasise panel (c) at the same instant. The forward rate kf[N₂O₄] is still falling and the reverse rate kr[NO₂]² is still rising — they have not yet met, so the mixture keeps changing.',
    state: { timeMarker: 2, panelView: 'Rate', initialN2O4: 1, motion: false } },
  { title: 'Equilibrium achieved',
    narration: 'Move into the shaded region. The two rate curves merge into one horizontal line and both concentration curves are flat: the plateau and the rate crossing happen at the very same time.',
    state: { timeMarker: 7, panelView: 'Both', initialN2O4: 1, motion: false } },
  { title: 'Equilibrium is dynamic, not static',
    narration: 'Switch on the molecular motion: N₂O₄ keeps splitting and NO₂ pairs keep recombining, yet the number of each stays constant because the two processes run at equal rates.',
    state: { timeMarker: 9, panelView: 'Rate', initialN2O4: 1, motion: true } },
  { title: 'Change the starting amount',
    narration: 'Raise the initial [N₂O₄]. The plateaus rise, the gas darkens and the dashed line shifts left because equal rates are reached sooner — but equilibrium is still defined by the rates becoming equal.',
    state: { timeMarker: 9, panelView: 'Both', initialN2O4: 1.8, motion: true } }
];
var stepIdx = 0;
function setInput(id, val) {
  var el = document.getElementById(id + 'Input'); if (el) el.value = val;
  var o = document.getElementById(id + 'Val'); if (o) o.value = val;
}
function applyStep(i) {
  stepIdx = (i + DEMO.length) % DEMO.length;
  var s = DEMO[stepIdx], st = s.state;
  document.getElementById('demoNarration').innerHTML = '<b>' + s.title + '</b><br>' + s.narration;
  document.getElementById('stepLabel').textContent = 'Step ' + (stepIdx + 1) + ' / ' + DEMO.length;
  setInput('initialN2O4', st.initialN2O4);
  update_initialN2O4(st.initialN2O4);
  document.getElementById('panelViewInput').value = st.panelView;
  toggle_panelView(st.panelView);
  setInput('timeMarker', st.timeMarker.toFixed(1));
  update_timeMarker(st.timeMarker);
  var mc = document.getElementById('moleculeMotionInput');
  mc.checked = !!st.motion; toggle_moleculeMotion(!!st.motion);
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

/* ─────────── boot ─────────── */
renderPlots();
updateTubes();
toggle_panelView('Both');
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

