    .stroke({ color: RED, width: 3.8, linecap: 'round', linejoin: 'round' });
  gBDyn.polyline(ptsOf(function (s) { return s.A; }, bxAt, byAt)).fill('none')
    .stroke({ color: BLUE, width: 3.8, linecap: 'round', linejoin: 'round' });
  gBDyn.line(dashX, BYB, dashX, topB).stroke({ color: '#000', width: 2.6, dasharray: '11,9' });
  bandText(gBDyn, (dashX + BX1) / 2, topB, BYB, plateauA);
  var tlab = Math.min(3.2, TEQ * 0.62), s3 = stateAt(tlab);
  chem(gBDyn, bxAt(tlab), byAt(s3.B) - 16, 25, P_NO2, { halo: true, anchor: 'middle' });
  chem(gBDyn, bxAt(tlab), byAt(s3.A) + 38, 25, P_N2O4, { halo: true, anchor: 'middle' });

  /* (c) rates */
  var rEq = rfOf(last), topC = cyAt(rEq);
  var shC = gCDyn.rect(CX1 - dashX, CYB - topC).move(dashX, topC).fill(YEL);
  gCDyn.polyline(ptsOf(rrOf, bxAt, cyAt)).fill('none')
    .stroke({ color: RED, width: 3.8, linecap: 'round', linejoin: 'round' });
  gCDyn.polyline(ptsOf(rfOf, bxAt, cyAt)).fill('none')
    .stroke({ color: BLUE, width: 3.8, linecap: 'round', linejoin: 'round' });
  gCDyn.line(dashX, CYB, dashX, topC).stroke({ color: '#000', width: 2.6, dasharray: '11,9' });
  bandText(gCDyn, (dashX + CX1) / 2, topC, CYB, null);
  var tf = TEQ * 0.26, tr = TEQ * 0.48;
  chem(gCDyn, bxAt(tf) + 10, cyAt(rfOf(stateAt(tf))) - 16, 24, P_KF, { halo: true });
  chem(gCDyn, bxAt(tr) + 10, cyAt(rrOf(stateAt(tr))) + 38, 24, P_KR, { halo: true });

  var hz = function (el, tip, title, body) {
    el.css('cursor', 'pointer')
      .on('mousemove', function (e) { showTooltip(tip, e); })
      .on('mouseleave', hideTooltip)
