function startDrag(e) { dragging = true; dragTo(e); if (e.preventDefault) e.preventDefault(); }
gB.on('mousedown', startDrag);
gC.on('mousedown', startDrag);
document.addEventListener('mousemove', function (e) { if (dragging) dragTo(e); });
document.addEventListener('mouseup', function () { dragging = false; });

